/* ---------- tides ---------- */
const EPOCH=Date.parse(TIDE.epoch),W=TIDE.speeds_deg_per_h.map(s=>s*Math.PI/180),NC=W.length,X=TIDE.x;
function hAt(ms){const t=(ms-EPOCH)/36e5;let h=X[0];for(let i=0;i<NC;i++)h+=X[1+i]*Math.cos(W[i]*t)+X[1+NC+i]*Math.sin(W[i]*t);return h;}
function extrema(a,b){const st=2*6e4,out=[];let p=hAt(a-st),c=hAt(a);
  for(let m=a;m<b;m+=st){const n=hAt(m+st);if(c>p&&c>=n)out.push({ms:m,h:c,k:"PM"});else if(c<p&&c<=n)out.push({ms:m,h:c,k:"BM"});p=c;c=n;}
  const cl=[];for(const e of out){const l=cl[cl.length-1];if(l&&l.k===e.k){if((e.k==="PM"&&e.h>l.h)||(e.k==="BM"&&e.h<l.h))cl[cl.length-1]=e;}else cl.push(e);}
  for(let i=0;i<cl.length;i++){const e=cl[i];if(e.k!=="PM")continue;const nb=[cl[i-1],cl[i+1]].filter(x=>x&&x.k==="BM");if(!nb.length)continue;
    const r=e.h-nb.reduce((s,x)=>s+x.h,0)/nb.length;e.coef=Math.max(20,Math.min(120,Math.round(TIDE.coef[0]*r+TIDE.coef[1])));}
  return cl;}
const TC={};function tidesOfDay(s){if(TC[s])return TC[s];const m=Date.parse(s+"T12:00:00Z");return TC[s]=extrema(m-23*36e5,m+23*36e5).filter(e=>ymd(new Date(e.ms))===s);}
function maxCoef(s){const c=tidesOfDay(s).filter(e=>e.coef).map(e=>e.coef);return c.length?Math.max(...c):null;}
function dayLows(s){return tidesOfDay(s).filter(e=>{const h=+hm(new Date(e.ms)).slice(0,2);return e.k==="BM"&&h>=7&&h<=19;});}

