/* Activités : grille des types (du plus demandé au moins demandé), puis chaque type en 4 lieux + « Voir les autres » */
const ACORD=["mer","sensations","culture","nature","sport","bienetre","sortie","plage"];
const gk=a=>a.cat==="enfants"?"sortie":a.cat;
const ACIC={mer:"wave",sensations:"spark",culture:"sail",enfants:"people",nature:"leaf",sport:"bike",bienetre:"drop",sortie:"film",plage:"shell",assos:"people"};
const ACLBL={sortie:"Sorties et loisirs"};
function actGrid(base,od){const n=k=>base.filter(a=>gk(a)===k).length,o=k=>base.filter(a=>gk(a)===k&&openOn(a,od)).length;
  const ks=ACORD.filter(k=>n(k)),na=(S.assos||[]).filter(a=>fitsWhere(TOWN_KM[a.town]??null,a.town)).length;
  const tile=(k,l,cnt,sub)=>`<button type="button" class="actile" data-act="cat" data-v="${S.cat===k?"tous":k}" aria-pressed="${S.cat===k}" style="--c:var(--i-${CATK[k]==="ink"?"act":CATK[k]||"act"})"><span class="actile-ic">${ic(ACIC[k]||"compass")}</span><span class="actile-t"><b>${esc(l)}</b><small>${cnt}${sub?` · ${sub}`:""}</small></span></button>`;
  return `<div class="acgrid" role="group" aria-label="Types d'activités">${ks.map(k=>{const x=o(k);return tile(k,ACLBL[k]||CATS[k],`${n(k)} lieu${n(k)>1?"x":""}`,x?`${x} ouvert${x>1?"s":""}`:"");}).join("")}${na?tile("assos","Associations",`${na} associations`,""):""}</div>
  ${S.cat!=="tous"?`<p class="ac-back"><button type="button" class="lnk" data-act="cat" data-v="tous">${ic("left","i-s")}Tous les types</button></p>`:""}`;}
function vActs(){const t=today(),od=S.openDay||t;
  const pre=ACTIV().filter(a=>actOK(a)&&fitsWhere(a.dist,a.town)&&(!S.free||/Gratuit/.test(a.price||"")));
  const base=pre.filter(a=>(!S.rain||a.rain)&&(!S.openToday||openOn(a,od)));
  if(S.cat==="enfants")S.cat="sortie";const list=base.filter(a=>S.cat==="tous"||gk(a)===S.cat).sort((p,q)=>(p.dist??99)-(q.dist??99));
  const nOpen=pre.filter(a=>(!S.rain||a.rain)&&openOn(a,od)).length,nRain=pre.filter(a=>a.rain&&(!S.openToday||openOn(a,od))).length;
  const g={};list.forEach(a=>(g[gk(a)] ||= []).push(a));
  const cats=[["tous","Tous les thèmes"],...Object.keys(CATS).filter(k=>k!=="saveurs"&&k!=="marche"&&pre.some(a=>a.cat===k)).map(k=>[k,CATS[k]]),["assos","Associations"]];
  return `${pageHead("À faire",`Activités : ${list.length} lieu${list.length>1?"x":""}, du plus proche au plus loin`)}
  ${segAC("activites")}
  <div class="filters">${frow("frow","Filtres",`${zoneSel()}${chipSel((WHO2().find(w=>w[0]===S.who)||WHO2()[0])[1],S.who,WHO2(),"who","tous")}${chip(`Ouvert ${od===t?"aujourd'hui":wdName(od)} <span class="chip-count">${nOpen}</span>`,S.openToday,'data-act="openT"')}${chip(`${ic("umb")}S'il pleut <span class="chip-count">${nRain}</span>`,S.rain,'data-act="rainT"')}${chip("Gratuit",S.free,'data-act="free"')}`)}</div>
  ${actGrid(base,od)}
  <div class="seg-wrap"><div class="seg seg-s" role="group" aria-label="Affichage"><button type="button" aria-pressed="${S.actView!=="carte"}" data-act="av" data-v="liste">Liste</button><button type="button" aria-pressed="${S.actView==="carte"}" data-act="av" data-v="carte">Carte</button></div></div>
  ${S.actView==="carte"?`<section class="sec" style="padding-top:4px">${mapSvg(list)}<button type="button" class="btn btn-quiet" data-act="kml">Exporter vers Google Maps</button><p class="status" id="kmlStatus" aria-live="polite"></p></section>`:""}
  <section class="sec grps" style="padding-top:0">${S.cat==="assos"?"":list.length?ACORD.filter(k=>g[k]).map(k=>{const c=`--c:var(--i-${CATK[k]==="ink"?"act":CATK[k]||"act"})`,all=S.cat!=="tous",L=all?g[k]:g[k].slice(0,4);
    return `<div class="group" style="${c}"><h2 class="group-title">${ACLBL[k]||CATS[k]}</h2><span class="group-count">${g[k].length}</span></div><ul style="${c}" class="list">${L.map(a=>placeRow(a,t)).join("")}</ul>${!all&&g[k].length>4?`<button type="button" class="ac-more" data-act="catgo" data-v="${k}">Voir les ${g[k].length-4} autres · ${esc(ACLBL[k]||CATS[k])}${ic("chev","i-s")}</button>`:""}`;}).join(""):`<p class="empty">Rien pour ces filtres. <button type="button" class="lnk" data-act="reset">Tout afficher</button></p>`}
  ${S.cat==="tous"||S.cat==="assos"?assosBlock():""}</section>
  <p class="foot">Une info à corriger ? Écrivez à <a href="mailto:contact@lepetitpref.fr">contact@lepetitpref.fr</a>.</p>`;}
const ATH=[["tous","Tout"],["sport","Sport"],["culture","Culture"],["loisirs","Loisirs"],["nature","Nature"],["solidarite","Solidarité"],["enfance","Enfance et parents"],["vie","Vie locale"]];
/* contact d'association : téléphones, e-mails et sites deviennent des liens (appeler, écrire, ouvrir) */
const linkify=t=>esc(t).replace(/https?:\/\/[^\s<]+/g,u=>`<a href="${u}" target="_blank" rel="noopener">${u.replace(/^https?:\/\/(www\.)?/,"").replace(/\/$/,"")} ↗</a>`)
  .replace(/(?<![\w@.\/])([\w.+-]+@[\w-]+\.[\w.-]+)/g,'<a href="mailto:$1">$1</a>')
  .replace(/(?<![\d\w])(0[1-9](?:[ .]?\d\d){4})(?!\d)/g,m=>`<a href="tel:${m.replace(/\D/g,"")}">${m}</a>`);
function assosBlock(){const L0=(S.assos||[]).filter(a=>fitsWhere(TOWN_KM[a.town]??null,a.town)),th=S.athm||"tous";
  const L=L0.filter(a=>th==="tous"||a.th===th).sort((a,b)=>(TOWN_KM[a.town]??99)-(TOWN_KM[b.town]??99)||(a.name||"").localeCompare(b.name||""));
  return `<div class="group" style="--c:var(--i-nat)"><h2 class="group-title">Associations</h2><span class="group-count">${L.length}</span></div>
   ${L0.length>12?`<div class="frow ath" role="group" aria-label="Thème des associations">${ATH.filter(([k])=>k==="tous"||L0.some(a=>a.th===k)).map(([k,l])=>chip(`${l} <span class="chip-count">${k==="tous"?L0.length:L0.filter(a=>a.th===k).length}</span>`,th===k,`data-act="athm" data-v="${k}"`)).join("")}</div>`:""}
   ${S.assos===null?loadingTxt:L.length?`<ul class="list" style="--c:var(--i-nat)">${L.map(a=>row({th:`<span class="thumb t-nat">${ic("people")}</span>`,title:esc(a.name),metaH:meta(esc(a.what||""),esc(townShort(a.town))),more:`${a.desc?`<p>${esc(a.desc)}</p>`:""}${a.regular?`<span class="row-meta">${esc(a.regular)}</span>`:""}${a.forWho?`<span class="row-meta">${esc(a.forWho)}</span>`:""}${a.contact?`<span class="row-meta asso-ct">${linkify(a.contact)}</span>`:""}${a.url?`<span class="row-links"><a href="${esc(a.url)}" target="_blank" rel="noopener">Site ↗</a></span>`:""}`})).join("")}</ul>`:`<p class="empty">Aucune association dans ce rayon.</p>`}`;}

/* formulaire de contact : envoi par Web3Forms si la clé est réglée (WEB3KEY), sinon ouverture d'un e-mail prérempli */
const WEB3KEY="";
document.addEventListener("submit",e=>{const f=e.target.closest("#cform");if(!f)return;e.preventDefault();
  const st=document.getElementById("cformS"),fd=new FormData(f),msg=(fd.get("message")||"").trim();
  if(msg.length<3){st.textContent="Écrivez quelques mots avant d'envoyer.";return;}
  if(fd.get("botcheck"))return;
  const sujet=fd.get("sujet"),mail=(fd.get("email")||"").trim();
  if(!WEB3KEY){location.href=`mailto:contact@lepetitpref.fr?subject=${encodeURIComponent("Le Petit Préf · "+sujet)}&body=${encodeURIComponent(msg+(mail?"\n\n"+mail:""))}`;st.textContent="Votre application d'e-mail s'ouvre avec le message prêt : il ne reste qu'à envoyer.";return;}
  const b=f.querySelector("button");b.disabled=true;st.textContent="Envoi…";
  fetch("https://api.web3forms.com/submit",{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({access_key:WEB3KEY,subject:"Le Petit Préf · "+sujet,from_name:"Le Petit Préf",message:msg,email:mail||undefined,page:location.hash})})
   .then(r=>r.json()).then(r=>{if(r.success){f.reset();st.textContent="Merci, c'est envoyé ! On regarde ça très vite.";}else throw 0;})
   .catch(()=>{st.innerHTML='Envoi impossible pour le moment. Écrivez à <a href="mailto:contact@lepetitpref.fr">contact@lepetitpref.fr</a>.';}).finally(()=>{b.disabled=false;});});
/* ===== Pêche à pied ===== */
/* Tailles minimales et quantités autorisées pour la pêche à pied de loisir.
   À remplir uniquement avec des données vérifiées (réglementation en vigueur pour la Loire-Atlantique).
   Format : especes:[{n:"Nom de l'espèce", taille:"x cm", quantite:"…", note:"…"}], source:"intitulé et lien du texte", maj:"AAAA-MM-JJ".
   Tant que la liste est vide, la page affiche « Tailles réglementaires : en cours de vérification ». */
const PECHE={source:"Réglette « Pêche à pied de loisir » du Syndicat mixte de la Baie de Bourgneuf (valable en Loire-Atlantique et Vendée), juin 2023, et fiche pêche à pied du Département de Loire-Atlantique. Repères indicatifs : seule la réglementation officielle fait foi (mairie, Affaires maritimes de Saint-Nazaire).",maj:"juin 2023",
 url:"https://www.baie-bourgneuf.com/wp-content/uploads/2023/06/Reglette-PAP-taille-recommandee-2023.pdf",
 especes:[
  {n:"Coque",taille:"2,7 cm",quantite:"4 kg (≈ 400)"},
  {n:"Palourde japonaise",taille:"3,5 cm",quantite:"3 kg (≈ 150)"},
  {n:"Huître creuse",taille:"5 cm",quantite:"60 huîtres, 5 kg max."},
  {n:"Huître plate",taille:"6 cm",quantite:"",note:"fiche du Département"},
  {n:"Moule",taille:"4 cm",quantite:"5 kg"},
  {n:"Pignon (telline)",taille:"2,5 cm",quantite:"2 kg (≈ 500)"},
  {n:"Couteau",taille:"10 cm",quantite:"",note:"fiche du Département"},
  {n:"Étrille",taille:"6,5 cm",quantite:"",note:"fiche du Département"},
  {n:"Crevette grise",taille:"3 cm",quantite:"",note:"fiche du Département"},
  {n:"Crevette rose",taille:"5 cm",quantite:"",note:"fiche du Département"}],
 regles:["Pas de pêche à moins de 15 m des parcs à huîtres et des bouchots, ni dans leurs allées.","Outils à main seulement (couteau à palourdes, griffe ou serfouette à 3 dents au plus) ; pas d'arrachage.","Ne grattez pas les herbiers de zostères ; laissez les crabes et crevettes porteurs d'œufs.","Certaines zones peuvent être fermées pour raison sanitaire : renseignez-vous en mairie avant de pêcher.","Amende jusqu'à 22 500 € en cas d'infraction."]};
function goodTides(n){const t=today(),out=[];for(let i=0;i<60&&out.length<n;i++){const d=addDays(t,i),c=maxCoef(d),l=dayLows(d);if(c>=70&&l.length)out.push({d,c,l});}return out;}
function vPeche(){return vMer();}
function pecheBody(){const T=goodTides(12),g=ACTS.find(a=>/Pêche à pied/.test(a.n));
  return `<h2 class="part-h" id="s-peche">Pêche à pied</h2><p class="part-sub">Les bonnes marées des prochaines semaines, calculées pour Préfailles.</p>
  ${sec("Prochaines bonnes marées","",T.length?`<ul class="list">${T.map(({d,c,l})=>row({lead:dateLead(d,d===today()),leadCls:"lead-date",title:`Basse mer ${l.map(x=>hm(new Date(x.ms))).join(" et ")}`,metaH:meta(`coef. ${c}`,c>=90?"grande marée":""),lines:[[`Créneau conseillé ${hm(new Date(l[0].ms-75*6e4))}–${hm(new Date(l[0].ms+75*6e4))}`,"ok"],[icsBtn({t:`Pêche à pied, coef. ${c}`,start:`${d.replace(/-/g,"")}T${hm(new Date(l[0].ms-75*6e4)).replace("h","")}00`,stop:`${d.replace(/-/g,"")}T${hm(new Date(l[0].ms+75*6e4)).replace("h","")}00`,loc:"Préfailles",desc:`Basse mer ${hm(new Date(l[0].ms))}. Repartez dès que la mer remonte.`}),""]]})).join("")}</ul>`:`<p class="empty">Pas de bonne marée de jour dans les deux prochains mois.</p>`,"Coefficient 70 et plus, basse mer entre 7 h et 19 h. Le créneau va de 1 h 15 avant à 1 h 15 après la basse mer.")}
  ${g?sec("Où aller","",`<ul class="list">${placeRow(g,today())}</ul>`):""}
  ${sec("Sécurité","",`<ul class="tips">
   <li>Regardez l'heure de la basse mer avant de partir et repartez dès que la mer remonte : par grand coefficient, elle revient vite.</li>
   <li>Repérez votre chemin de retour. Les chenaux et les cuvettes se remplissent en premier et peuvent vous couper du rivage.</li>
   <li>N'y allez pas seul, prévenez quelqu'un, gardez un téléphone chargé dans une poche étanche.</li>
   <li>Chaussures fermées : rochers glissants et coquillages coupants.</li>
   <li>Brouillard, orage ou vent qui forcit : on remonte tout de suite.</li>
   <li>Remettez les rochers retournés à leur place et ne prélevez que ce que vous mangerez.</li>
   <li>Personne en difficulté en mer ou sur l'estran : appelez le <a href="tel:196">196</a> (ou le <a href="tel:112">112</a>).</li></ul>`)}
  ${sec("Tailles et quantités","",PECHE.especes.length?`<table class="tbl"><thead><tr><th>Espèce</th><th>Taille min.</th><th>Quantité</th></tr></thead><tbody>${PECHE.especes.map(x=>`<tr><td>${esc(x.n)}${x.note?`<br><span class="dim">${esc(x.note)}</span>`:""}</td><td>${esc(x.taille||"")}</td><td>${esc(x.quantite||"")}</td></tr>`).join("")}</tbody></table><p class="sec-note" style="margin-top:8px">${esc(PECHE.source)}${PECHE.url?` <a href="${PECHE.url}" target="_blank" rel="noopener">Voir la réglette ↗</a>`:""}</p><h3 class="sec-sub" style="margin:14px 0 4px;font-size:15px">Les règles à connaître</h3>${(PECHE.regles||[]).map(r=>`<p class="sec-note" style="margin:6px 0">• ${esc(r)}</p>`).join("")}`:`<p class="textline" style="border-top:0"><b>Tailles réglementaires :</b> en cours de vérification.</p>`)}
  <p class="foot">Certaines zones peuvent être fermées pour raison sanitaire : en cas de doute, appelez la mairie au <a href="tel:0240216037">02 40 21 60 37</a>.</p>`;}

