  box.innerHTML=`<p class="nav-src">Chargement des prévisions…</p>`;const z=ZPT[SPOTZ[id]??0];
  const W=`https://api.open-meteo.com/v1/forecast?latitude=${sp.lat}&longitude=${sp.lon}&hourly=wind_speed_10m,wind_gusts_10m,wind_direction_10m&models=${FCM.w.map(m=>m[0]).join(",")}&wind_speed_unit=kn&timezone=Europe%2FParis&forecast_days=4`;
  const M=`https://marine-api.open-meteo.com/v1/marine?latitude=${z[0]}&longitude=${z[1]}&hourly=wave_height,wave_period,wave_direction&models=${FCM.v.map(m=>m[0]).join(",")}&timezone=Europe%2FParis&forecast_days=4`;
